/**
 * Internationalisation (i18n) cho landing app (Home + JobDetails + Layout).
 *
 * Thiết kế đồng bộ với các trang login/password/2FA/success ở /signin/* —
 *   • dùng chung localStorage key `preferredLang`, `langManual`, `langAutoCC`
 *     để ngôn ngữ được chọn ở trang nào cũng persist sang trang kia;
 *   • dùng chung localStorage key `geoInfo` cache (ipwho.is) để không fetch
 *     nhiều lần.
 *
 * Cơ chế auto-detect (chỉ chạy 1 lần / session, hoặc tới khi cache geoInfo
 * hết hiệu lực):
 *   1. Nếu user đã bấm đổi ngôn ngữ tay (`langManual === '1'`) → respect.
 *   2. Else: đọc country_code từ `geoInfo` cache → nếu có → map sang lang.
 *   3. Else: fetch `https://ipwho.is/?fields=ip,country,country_code,success`
 *      với timeout 2.5s, lưu vào `geoInfo` + `preferredLang` + `langAutoCC`.
 *   4. Fallback: navigator.language / 'en'.
 *
 * Translation dictionary chỉ bao phủ các string visible chính (nav, footer,
 * hero, form). Các string còn lại (body content dài) giữ nguyên English —
 * user có thể mở rộng dictionary trong TRANSLATIONS bên dưới khi cần.
 */

import {
  createContext, useContext, useEffect, useMemo, useState, useRef,
  type ReactNode,
} from 'react';

