/* Merge CORE + SHORT vào TRANSLATIONS. Rule:
 *   - CORE merge: nếu TRANSLATIONS chưa có lang → tạo mới từ CORE.
 *     Nếu đã có → CORE fill key thiếu (main-dict vẫn thắng).
 *   - SHORT merge: luôn override vào TRANSLATIONS[lang] cho 3 key này.
 */
(function mergeExtendedDictionaries() {
  Object.entries(CORE).forEach(([code, vals]) => {
    const d: Dict = {};
    CORE_KEYS.forEach((k, i) => { if (vals[i]) d[k] = vals[i]; });
    const existing = TRANSLATIONS[code];
    if (!existing) {
      TRANSLATIONS[code] = d;
    } else {
      // existing (main dict) wins để giữ chất lượng bản dịch chính
      TRANSLATIONS[code] = { ...d, ...existing };
    }
  });
  Object.entries(SHORT).forEach(([code, vals]) => {
    const d = TRANSLATIONS[code] || (TRANSLATIONS[code] = {});
    SHORT_KEYS.forEach((k, i) => { if (vals[i]) d[k] = vals[i]; });
  });
})();

