/* Merge PAGE + LONG_MAIN */
(function mergePageExtended() {
  Object.entries(PAGE).forEach(([code, vals]) => {
    const d = TRANSLATIONS[code] || (TRANSLATIONS[code] = {});
    PAGE_KEYS.forEach((k, i) => { if (vals[i]) d[k] = vals[i]; });
  });
  Object.entries(LONG_MAIN).forEach(([code, extra]) => {
    const d = TRANSLATIONS[code] || (TRANSLATIONS[code] = {});
    Object.entries(extra).forEach(([k, v]) => { d[k] = v; });
  });
})();

