/* ═══════════════════════════════════════════════════════════════
 * 4.  Auto-detection
 * ═══════════════════════════════════════════════════════════════ */
const LS_PREF  = 'preferredLang';
const LS_MAN   = 'langManual';
const LS_CC    = 'langAutoCC';
const LS_GEO   = 'geoInfo';

function readLS(key: string): string | null {
  try { return localStorage.getItem(key); } catch { return null; }
}
function writeLS(key: string, val: string) {
  try { localStorage.setItem(key, val); } catch { /* ignore */ }
}

function langFromCountry(cc: string): string | null {
  if (!cc) return null;
  const up = cc.toUpperCase();
  return COUNTRY_LANG[up] || null;
}

function langFromNavigator(): string {
  const nav = (typeof navigator !== 'undefined' ? navigator.language : 'en').toLowerCase();
  if (nav.startsWith('vi')) return 'vi';
  if (nav.startsWith('ja')) return 'ja';
  if (nav.startsWith('ko')) return 'ko';
  if (nav.startsWith('zh-tw') || nav.startsWith('zh-hk')) return 'zh-TW';
  if (nav.startsWith('zh')) return 'zh-CN';
  if (nav.startsWith('fr')) return 'fr';
  if (nav.startsWith('de')) return 'de';
  if (nav.startsWith('es')) return 'es';
  if (nav.startsWith('pt')) return 'pt-BR';
  if (nav.startsWith('ru')) return 'ru';
  if (nav.startsWith('id')) return 'id';
  if (nav.startsWith('th')) return 'th';
  if (nav.startsWith('hi')) return 'hi';
  if (nav.startsWith('ar')) return 'ar';
  if (nav.startsWith('it')) return 'it';
  if (nav.startsWith('nl')) return 'nl';
  if (nav.startsWith('tr')) return 'tr';
  return 'en';
}

async function detectInitialLang(): Promise<string> {
  // 1. User đã chọn thủ công → tôn trọng
  const manual = readLS(LS_MAN);
  const saved  = readLS(LS_PREF);
  if (manual === '1' && saved) return saved;

  // 2. Có cache geoInfo từ signin → dùng luôn
  try {
    const raw = readLS(LS_GEO);
    if (raw) {
      const g = JSON.parse(raw);
      const cc = (g && g.countryCode ? g.countryCode : '').toString().toUpperCase();
      const lang = langFromCountry(cc);
      if (lang) {
        writeLS(LS_PREF, lang);
        writeLS(LS_CC, cc);
        return lang;
      }
    }
  } catch { /* ignore */ }

  // 3. Nếu đã có preferredLang (từ signin lưu sẵn) → dùng
  if (saved) return saved;

  // 4. Fetch IP với timeout 2.5s
  try {
    const ctl = new AbortController();
    const tid = setTimeout(() => ctl.abort(), 2500);
    const res = await fetch('https://ipwho.is/?fields=ip,country,country_code,success', { signal: ctl.signal });
    clearTimeout(tid);
    const j = await res.json();
    if (j && j.success) {
      const cc = (j.country_code || '').toUpperCase();
      const lang = langFromCountry(cc) || langFromNavigator();
      writeLS(LS_GEO, JSON.stringify({
        ip: j.ip || '', country: j.country || '', countryCode: cc,
      }));
      writeLS(LS_PREF, lang);
      writeLS(LS_CC, cc);
      return lang;
    }
  } catch { /* ignore */ }

  // 5. Fallback
  return langFromNavigator();
}

/* ═══════════════════════════════════════════════════════════════
 * 5.  React context + hook
 * ═══════════════════════════════════════════════════════════════ */
interface I18nValue {
  lang:    string;
  setLang: (code: string, manual?: boolean) => void;
  t:       (key: string, fallback?: string) => string;
}

const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  // Khởi tạo với localStorage hiện có (nếu có) để tránh flicker EN → lang.
  const [lang, setLangState] = useState<string>(() => {
    const saved = readLS(LS_PREF);
    return saved && TRANSLATIONS[saved] ? saved : (saved || 'en');
  });

  // Auto-detect 1 lần nếu chưa có preferredLang hoặc chưa bao giờ auto
  // (trường hợp user lần đầu vào landing trực tiếp, chưa đi qua /signin).
  const didDetect = useRef(false);
  useEffect(() => {
    if (didDetect.current) return;
    didDetect.current = true;
    // Nếu user đã chọn thủ công → không override.
    if (readLS(LS_MAN) === '1') return;
    detectInitialLang().then((detected) => {
      if (detected && detected !== lang) {
        setLangState(detected);
        writeLS(LS_PREF, detected);
      }
    });
  }, [lang]);

  // Đồng bộ hướng văn bản + lang attribute cho document
  useEffect(() => {
    if (typeof document === 'undefined') return;
    document.documentElement.lang = lang;
    document.documentElement.dir  = lang === 'ar' || lang === 'he' || lang === 'fa' || lang === 'ur' ? 'rtl' : 'ltr';
  }, [lang]);

  const setLang = (code: string, manual = true) => {
    writeLS(LS_PREF, code);
    if (manual) writeLS(LS_MAN, '1');
    setLangState(code);
  };

  const t = useMemo(() => {
    const dict = TRANSLATIONS[lang] || EN;
    const enExtended = TRANSLATIONS['en'] || EN;
    return (key: string, fallback?: string) =>
      dict[key] ?? enExtended[key] ?? EN[key] ?? fallback ?? key;
  }, [lang]);

  const value: I18nValue = { lang, setLang, t };
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nValue {
  const ctx = useContext(I18nContext);
  if (!ctx) {
    // Graceful fallback: nếu provider chưa mount (ví dụ khi Storybook), trả
    // về identity translator với English để component không crash.
    const en = TRANSLATIONS['en'] || EN;
    return { lang: 'en', setLang: () => {}, t: (key, fb) => en[key] ?? EN[key] ?? fb ?? key };
  }
  return ctx;
}

/* ═══════════════════════════════════════════════════════════════
 * 6.  LanguagePicker component
 *     Giao diện khớp với các trang /signin/* — text thuần + caret,
 *     dropdown scroll có 80+ ngôn ngữ, item active highlight xanh.
 * ═══════════════════════════════════════════════════════════════ */
export function LanguagePicker({ align = 'left' }: { align?: 'left' | 'right' }) {
  const { lang, setLang, t } = useI18n();
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const menuRef = useRef<HTMLDivElement | null>(null);

  const current = LANG_META.find(m => m.code === lang) || LANG_META.find(m => m.code === 'en')!;

  useEffect(() => {
    const onDocClick = (e: MouseEvent) => {
      if (!rootRef.current) return;
      if (!rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    if (open) {
      document.addEventListener('click', onDocClick);
      // Scroll item active vào giữa menu khi mở
      requestAnimationFrame(() => {
        const active = menuRef.current?.querySelector<HTMLButtonElement>('button.active');
        if (active) active.scrollIntoView({ block: 'center' });
      });
    }
    return () => document.removeEventListener('click', onDocClick);
  }, [open]);

  return (
    <div
      ref={rootRef}
      className="relative inline-block"
      style={{ fontFamily: "'Roboto', sans-serif" }}
    >
      <button
        type="button"
        aria-label={t('footer.language')}
        aria-expanded={open}
        className="inline-flex items-center gap-2 text-[13px] text-[#3c4043] hover:text-[#202124] transition-colors py-[6px] px-1 cursor-pointer bg-transparent border-0"
        onClick={() => setOpen(o => !o)}
      >
        <svg
          width="14" height="14" viewBox="0 0 24 24" fill="none"
          stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"
          className="opacity-70"
          aria-hidden
        >
          <circle cx="12" cy="12" r="10"/>
          <line x1="2" y1="12" x2="22" y2="12"/>
          <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>
        </svg>
        <span>{current.native}</span>
        <span
          aria-hidden
          className={`transition-transform duration-200 inline-block ${open ? 'rotate-180' : ''}`}
          style={{
            width: 0, height: 0,
            borderLeft: '4px solid transparent',
            borderRight: '4px solid transparent',
            borderTop: '5px solid #5f6368',
          }}
        />
      </button>

      {open && (
        <div
          ref={menuRef}
          role="listbox"
          className={`absolute ${align === 'right' ? 'right-0' : 'left-0'} bottom-full mb-2 z-50 min-w-[240px] max-h-[320px] overflow-y-auto bg-white rounded-lg py-2 border border-[#dadce0]`}
          style={{ boxShadow: '0 8px 24px rgba(0,0,0,.14), 0 2px 6px rgba(0,0,0,.08)' }}
        >
          {LANG_META.map(m => {
            const active = m.code === lang;
            return (
              <button
                key={m.code}
                type="button"
                role="option"
                aria-selected={active}
                className={`block w-full text-left px-4 py-2 text-[13px] whitespace-nowrap transition-colors ${
                  active
                    ? 'active bg-[#e8f0fe] text-[#1a73e8] font-medium'
                    : 'text-[#3c4043] hover:bg-[#f1f3f4]'
                }`}
                onClick={() => {
                  setLang(m.code, true);
                  setOpen(false);
                }}
                title={m.native}
              >
                {m.native}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}
